### libdrm: The View from User Space
Now let's trace the flow above directly from user space. The following program opens a DRM device, prints driver details, and lists KMS objects.  

```c
{
    "title": "drm_probe.c - List driver info and KMS objects",
    "ln": true
}
---
// drm_probe.c — Opens a DRM device and lists driver info and KMS objects (CRTCs, connectors, planes).
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <xf86drm.h>
#include <xf86drmMode.h>

static const char *plane_type(int fd, uint32_t plane_id)
{
	static const char *names[] = { "overlay", "primary", "cursor" };
	drmModeObjectProperties *props =
		drmModeObjectGetProperties(fd, plane_id, DRM_MODE_OBJECT_PLANE);
	const char *ret = "?";

	for (uint32_t i = 0; props && i < props->count_props; i++) {
		drmModePropertyRes *p = drmModeGetProperty(fd, props->props[i]);
		if (p && !strcmp(p->name, "type") && props->prop_values[i] < 3)
			ret = names[props->prop_values[i]];
		drmModeFreeProperty(p);
	}
	drmModeFreeObjectProperties(props);
	return ret;
}

int main(int argc, char **argv)
{
	const char *path = argc > 1 ? argv[1] : "/dev/dri/card0";
	int fd = open(path, O_RDWR | O_CLOEXEC);

	if (fd < 0) { perror(path); return 1; }

	drmVersionPtr v = drmGetVersion(fd);  // [!code highlight]
	printf("driver : %s %d.%d.%d (%s)\n", v->name, v->version_major,
	       v->version_minor, v->version_patchlevel, v->desc);
	drmFreeVersion(v);

	uint64_t cap;
	if (!drmGetCap(fd, DRM_CAP_DUMB_BUFFER, &cap))  // [!code highlight]
		printf("cap    : DUMB_BUFFER=%llu\n", (unsigned long long)cap);
	if (!drmGetCap(fd, DRM_CAP_PRIME, &cap))  // [!code highlight]
		printf("cap    : PRIME=0x%llx (import=%d, export=%d)\n", (unsigned long long)cap,
		       !!(cap & DRM_PRIME_CAP_IMPORT), !!(cap & DRM_PRIME_CAP_EXPORT));

	// To use atomic, it must first be enabled per file (fd) — this corresponds to file_priv->atomic in the kernel.
	printf("client : UNIVERSAL_PLANES=%d ATOMIC=%d\n",
	       !drmSetClientCap(fd, DRM_CLIENT_CAP_UNIVERSAL_PLANES, 1),  // [!code highlight]
	       !drmSetClientCap(fd, DRM_CLIENT_CAP_ATOMIC, 1));  // [!code highlight]

	drmModeRes *res = drmModeGetResources(fd);  // [!code highlight]
	if (!res) { perror("drmModeGetResources"); return 1; }  // [!code highlight]
	printf("crtcs=%d encoders=%d connectors=%d\n", res->count_crtcs,
	       res->count_encoders, res->count_connectors);

	for (int i = 0; i < res->count_connectors; i++) {
		drmModeConnector *c = drmModeGetConnector(fd, res->connectors[i]);
		printf("  connector %u: %s-%u %s, %d modes", c->connector_id,
		       drmModeGetConnectorTypeName(c->connector_type), c->connector_type_id,
		       c->connection == DRM_MODE_CONNECTED ? "connected" : "disconnected",
		       c->count_modes);
		if (c->count_modes)
			printf(", preferred %s @%uHz", c->modes[0].name, c->modes[0].vrefresh);
		printf("\n");
		drmModeFreeConnector(c);
	}

	drmModePlaneRes *pr = drmModeGetPlaneResources(fd);  // [!code highlight]
	for (uint32_t i = 0; pr && i < pr->count_planes; i++) {
		drmModePlane *p = drmModeGetPlane(fd, pr->planes[i]);
		printf("  plane %u: %s, possible_crtcs=0x%x, %u formats\n", p->plane_id,
		       plane_type(fd, p->plane_id), p->possible_crtcs, p->count_formats);
		drmModeFreePlane(p);
	}
	drmModeFreePlaneResources(pr);
	drmModeFreeResources(res);
	close(fd);
	return 0;
}
```
Each libdrm function maps directly to <b>a single kernel ioctl</b>. You can match the exact names from the `drm_ioctls[]` table in the code above:  

| libdrm Function | ioctl | Kernel Handler | Flags |
|---|---|---|---|
| `drmGetVersion()` | `DRM_IOCTL_VERSION` | `drm_version()` | RENDER_ALLOW |
| `drmGetCap()` | `DRM_IOCTL_GET_CAP` | `drm_getcap()` | RENDER_ALLOW |
| `drmSetClientCap()` | `DRM_IOCTL_SET_CLIENT_CAP` | `drm_setclientcap()` | None |
| `drmModeGetResources()` | `DRM_IOCTL_MODE_GETRESOURCES` | `drm_mode_getresources()` | None |
| `drmModeGetConnector()` | `DRM_IOCTL_MODE_GETCONNECTOR` | `drm_mode_getconnector()` | None |
| `drmModeGetPlaneResources()` | `DRM_IOCTL_MODE_GETPLANERESOURCES` | `drm_mode_getplane_res()` | None |
| `drmModeObjectGetProperties()` | `DRM_IOCTL_MODE_OBJ_GETPROPERTIES` | `drm_mode_obj_get_properties_ioctl()` | None |

This program has been verified to compile with `libdrm 2.4.129`. Running it requires access permissions to `/dev/dri/card0` (usually available in a desktop login session, or requires membership in the `video`/`render` group). Running `strace -e trace=openat,ioctl ./drm_probe` shows the sequence of ioctls invoked by the user (depending on the strace version, it will also display decoded names such as `DRM_IOCTL_VERSION`).  

